def sum_combinations(candidates: list[int], target: int) -> list[list[int]]:
    nums = sorted(candidates)
    res, path = [], []

    def bt(start: int, remain: int) -> None:
        if remain == 0:
            res.append(path[:])
            return
        for i in range(start, len(nums)):
            if nums[i] > remain:
                break
            path.append(nums[i])
            bt(i, remain - nums[i])
            path.pop()

    bt(0, target)
    return res
